node --input-type=module <<'JS'
import { registerHooks } from 'node:module';
import { existsSync } from 'node:fs';
registerHooks({resolve(s,c,n) {
  if (c.parentURL?.startsWith(new URL('./src/', import.meta.url).href) && s.startsWith('.') && s.endsWith('.js')) {
    const url = new URL(s.replace(/\.js$/, '.ts'), c.parentURL);
    if (existsSync(url)) return n(url.href,c);
  }
  return n(s,c);
}});
const {loadVendorFile} = await import('./tools/node-vendor.mjs');
for (const path of ['compiler/typed/tape.js','compiler/typed/typed-wasm.js','bench/host/rv32-interp.js','compiler/typed/typed-rv32.js']) loadVendorFile(path);
const {setVendor} = await import('./src/typed/vendor.ts');
setVendor({typedTape, typedWasm, typedRv32Interp, typedRv32});
const {Program} = await import('./src/typed/program.ts');
const {storeOf} = await import('./src/typed/ir.ts');
const {evaluate,casesFrom} = await import('./src/typed/evaluate.ts');
const p = new Program('probe', \`record Pair { re: f32; im: f32; }
function cmul(a: f32, b: f32): Pair { return Pair { re: a * b, im: a + b }; }
function probe(work: buffer, sizes: buffer): i32 {
    let m = 1 << sizes.charCodeAt(0);
    for (let i = 0; i < m; i = i + 1) {
        const q: Pair = cmul(work.getF32(i), 0.5);
        work.setF32(i, q.re - q.im);
    }
    return m;
}\`, {inputs:{cmul:{a:[-1,1],b:[-1,1]},probe:{work:{floats:[8,8],range:[-1,1]},sizes:{buffer:[1,1],cell:[1,3]}}}});
if(p.status !== 'ok') throw new Error(JSON.stringify(p.origin.value));
const s=storeOf(p.origin.value);
const c=casesFrom(s,'probe',{count:1,inputs:p.inputs.probe})[0];
const inView=new DataView(c.memory.buffer,c.memory.byteOffset,c.memory.byteLength);
const x=inView.getFloat32(c.args[0]+4,true);
const r=evaluate(s,'probe',c.args,c.memory,{limit:20000});
const outView=new DataView(r.bytes.buffer,r.bytes.byteOffset,r.bytes.byteLength);
if(r.trap || !Object.is(outView.getFloat32(c.args[0]+4,true),Math.fround(Math.fround(x * 0.5)-Math.fround(x+0.5)))) throw new Error(JSON.stringify(r));
const B=await import('./src/typed/backend/index.ts');
const run=B.runImage(B.lowerToImage(p.head).image,'probe',c.args,c.memory,{limit:200000});
const exact=await import('./src/typed/evaluate.ts');
if (!exact.agrees(r,run)) throw new Error('workbench RV32 differs: '+JSON.stringify(run));
const ref=typedRv32.compile(p.source,[],undefined);
const q=B.runImage(B.imageFromCode('probe',ref.image,ref.entries),'probe',c.args,c.memory,{limit:200000});
if (!exact.agrees(r,q)) throw new Error('reference RV32 differs: '+JSON.stringify(q));
const speed=await p.pipeline('speed');
console.log(JSON.stringify({x,out:outView.getFloat32(c.args[0]+4,true),steps:r.steps,rv32:run.steps,reference:q.steps,rev:p.rev,check:p.check().fns.map(({fn,status,total,bothTrap,inconclusive})=>({fn,status,total,bothTrap,inconclusive}))}));
