node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
const path = 'ttmp/2026/11/26/IRWB-016--f32-dsp/design-doc/01-f32-dsp-corpus-program.md';
const body = readFileSync(path, 'utf8');
const links = [...body.matchAll(/\]\((\.\.?\/[^)]+)\)/g)];
for (const [,link] of links) assert(existsSync(resolve(dirname(path),link)), link);
const { inputs } = JSON.parse(body.match(/\`\`\`json\n([\s\S]+?)\n\`\`\`/)[1]);
const cells = inputs.fft.roots.cells;
const v = new DataView(new ArrayBuffer(4));
const roots = [];
for(let i=0;i<cells.length;i+=2) {
  v.setUint16(0,cells[i],true);
  v.setUint16(2,cells[i+1],true);
  roots.push(v.getFloat32(0,true));
}
assert.deepEqual(roots,[-1,0,0,-1,...[8,16,32].flatMap(n=>[Math.fround(Math.cos(-2*Math.PI/n)),Math.fround(Math.sin(-2*Math.PI/n))])]);
assert.equal(inputs.biquadBank.out.buffer[0],2*32*3);
const eps=2**-23;
const b0=0.25*(1-eps), x=1-eps, b1=-0.25*(1-2*eps);
assert.equal(Math.fround(Math.fround(b0*x)+b1),0);
assert.equal(Math.fround(b0*x+b1),2**-48);
assert(20*Math.log10(2**-48)<-100);
console.log('Valid project JSON, stage-root cells, rounding witness and '+links.length+' relative links');
